package com.mygo.music;

import android.app.*;
import android.content.*;
import android.media.MediaPlayer;
import android.os.SystemClock;
import android.widget.TextView;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Quality retry buttons, late logins, live status and honest metadata against real AAC playback. */
final class QualityRetryChecks {
    final Instrumentation test;final Context context;final CompletionChecks helper;
    QualityRetryChecks(Instrumentation test){this.test=test;context=test.getTargetContext();helper=new CompletionChecks(test);}
    interface Action{void run()throws Exception;}
    void ui(Action action)throws Exception{Throwable[] error={null};test.runOnMainSync(()->{try{action.run();}catch(Throwable failure){error[0]=failure;}});if(error[0]!=null)throw new AssertionError("Quality retry action failed",error[0]);}
    static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    static Object invoke(Object object,String name)throws Exception{java.lang.reflect.Method method=object.getClass().getDeclaredMethod(name);method.setAccessible(true);return method.invoke(object);}
    void tier(PlaybackService service,String quality,long previous)throws Exception{helper.await(()->{PlaybackService.Snapshot state=service.snapshot();return state.ready&&!state.qualitySwitching&&state.requestedQuality.equals(quality)&&state.generation>previous;},"new quality request was not adopted: "+quality);}
    void clock(PlaybackService service)throws Exception{ui(service::resume);int before=service.snapshot().position;helper.await(()->service.snapshot().playing&&service.snapshot().position>before+150,"quality native audio clock did not advance");}
    void unchanged(PlaybackService service,PlaybackService.Snapshot before)throws Exception{ui(()->{PlaybackService.Snapshot after=service.snapshot();check(after.player==before.player&&after.generation==before.generation&&!after.qualitySwitching&&after.requestedQuality.equals(before.requestedQuality),"obsolete quality retry replaced the current session or choice");});}
    String panel(MainActivity activity)throws Exception{return ((TextView)FullPortChecks.field(activity,"qualityDetails")).getText().toString();}
    void run()throws Exception{
        String id="quality-retry",track="plugin://"+id+"?id=one";helper.cleanup(id);
        SharedPreferences prefs=context.getSharedPreferences("library",0),data=context.getSharedPreferences("plugin_data_"+id,0);Map<String,?> original=new HashMap<>(prefs.getAll());prefs.edit().remove("selected_source").putBoolean("auto_cache",false).putBoolean("plugin_network_"+id,true).commit();
        MainActivity activity=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));PlaybackService[] connected={null};helper.await(()->{connected[0]=(PlaybackService)FullPortChecks.field(activity,"playbackService");return connected[0]!=null;},"quality retry service missing");PlaybackService service=connected[0];PluginManager manager=new PluginManager(activity);AudioCache cache=AudioCache.shared(context);for(String q:AudioQuality.VALUES)cache.remove(track,q);
        NativeAudioChecks transport=new NativeAudioChecks(test);
        try(NativeAudioChecks.Server server=transport.new Server(false)){
            helper.install(manager,id,"stream",new JSONArray(),"export async function stream({quality}){host.storage.set('calls',(host.storage.get('calls')||0)+1);if(quality==='lossless'&&!host.storage.get('allowed')){const e=Error('fixture membership required');e.code='signIn';throw e;}if(host.storage.get('holdStream')){host.storage.set('streamPending',true);await new Promise(r=>setTimeout(r,1400));}return {url:'"+server.base()+"/quality-aac.m4a',type:'aac',quality,bitRate:96000,bitRateUnit:'bps',sampleRate:44100};}export async function signIn(){host.storage.set('loginPending',true);await new Promise(r=>setTimeout(r,1400));host.storage.set('allowed',true);return {id:'fixture'};}");
            JSONArray queue=new JSONArray().put(new JSONObject().put("uri",track).put("title","Quality retry original").put("scope","selected-list"));ui(()->{service.clearQueue();PlaybackService.startQueue(context,queue,0,0,43,true,true,"high");});helper.await(()->service.snapshot().playing&&service.snapshot().position>200,"initial real AAC did not play");ui(()->{service.pause();service.seek(1800);});helper.await(()->Math.abs(service.snapshot().position-1800)<200,"quality retry baseline seek failed");
            long issue=service.snapshot().qualityIssueId;ui(()->service.changeQuality("lossless"));helper.await(()->!service.snapshot().qualitySwitching&&service.snapshot().qualityIssueId>issue,"quality authorization failure did not finish");PlaybackService.Snapshot failed=service.snapshot();MediaPlayer originalPlayer=failed.player;data.edit().putString("allowed","true").commit();SourcePlaylistUiChecks.click(test,"重试");tier(service,"lossless",failed.generation);
            ui(()->{PlaybackService.Snapshot state=service.snapshot();check(!state.playing&&state.player!=originalPlayer&&Math.abs(state.position-1800)<250,"quality retry lost paused position");check(state.volume==43&&state.shuffle&&state.repeat&&service.queueSnapshot().toString().equals(queue.toString()),"quality retry changed selected list or controls");check(state.qualityInfo.contains("无损标注与编码不符")&&state.qualityInfo.contains("AAC")&&state.qualityInfo.contains("96 kbps"),"real AAC was displayed as confirmed lossless");check(!service.retryQuality(failed),"consumed quality error could be retried again");});clock(service);ui(service::pause);

            long beforeHigh=service.snapshot().generation;ui(()->service.changeQuality("high"));tier(service,"high",beforeHigh);
            data.edit().putString("holdStream","true").putString("streamPending","false").commit();long beforePanel=service.snapshot().generation;ui(()->{service.changeQuality("lossless");invoke(activity,"showPlaybackQuality");});helper.await(()->panel(activity).contains("正在准备新音质"),"quality panel did not show pending preparation");tier(service,"lossless",beforePanel);helper.await(()->panel(activity).contains("无损标注与编码不符")&&!panel(activity).contains("正在准备新音质"),"open quality panel did not update after adoption");ui(()->{AlertDialog dialog=(AlertDialog)FullPortChecks.field(activity,"qualityDialog");check(dialog.getListView().getCheckedItemPosition()==2,"live quality panel selected a stale tier");dialog.dismiss();});data.edit().putString("holdStream","false").commit();

            long back=service.snapshot().generation;ui(()->service.changeQuality("high"));tier(service,"high",back);data.edit().putString("allowed","false").commit();long previous=service.snapshot().qualityIssueId;final long sameSongIssue=previous;ui(()->service.changeQuality("lossless"));helper.await(()->service.snapshot().qualityIssueId>sameSongIssue&&!service.snapshot().qualitySwitching,"same-song stale fixture did not fail");PlaybackService.Snapshot stale=service.snapshot();JSONArray replacement=new JSONArray().put(new JSONObject().put("uri",track).put("title","Same song, new session"));ui(()->PlaybackService.startQueue(context,replacement,0,0,80,false,false,"high"));tier(service,"high",stale.generation);clock(service);PlaybackService.Snapshot sameSong=service.snapshot();data.edit().putString("allowed","true").commit();SourcePlaylistUiChecks.click(test,"重试");unchanged(service,sameSong);

            data.edit().putString("allowed","false").commit();previous=service.snapshot().qualityIssueId;final long loginIssue=previous;ui(()->service.changeQuality("lossless"));helper.await(()->service.snapshot().qualityIssueId>loginIssue&&!service.snapshot().qualitySwitching,"late login quality fixture did not fail");SourcePlaylistUiChecks.click(test,"登录后重试");helper.await(()->data.getString("loginPending","false").equals("true"),"quality login did not begin");long beforeStandard=service.snapshot().generation;ui(()->service.changeQuality("standard"));tier(service,"standard",beforeStandard);PlaybackService.Snapshot latest=service.snapshot();helper.await(()->data.getString("allowed","false").equals("true"),"quality login never returned");SystemClock.sleep(200);test.waitForIdleSync();unchanged(service,latest);clock(service);

            // A new pending replacement may have the same generation as the old error.
            data.edit().putString("allowed","false").commit();final long pendingIssue=service.snapshot().qualityIssueId;ui(()->service.changeQuality("lossless"));helper.await(()->service.snapshot().qualityIssueId>pendingIssue&&!service.snapshot().qualitySwitching,"pending replacement fixture did not fail");PlaybackService.Snapshot pendingFailure=service.snapshot();data.edit().putString("holdStream","true").putString("streamPending","false").commit();ui(()->service.changeQuality("high"));helper.await(()->data.getString("streamPending","false").equals("true"),"new quality never reached delayed source");Object pending=FullPortChecks.field(service,"qualityChange");SourcePlaylistUiChecks.click(test,"重试");ui(()->check(FullPortChecks.field(service,"qualityChange")==pending&&!service.retryQuality(pendingFailure),"old error cancelled a newer pending quality in the same generation"));tier(service,"high",pendingFailure.generation);data.edit().putString("holdStream","false").commit();

            // Store and replay the actual AAC bytes offline with the deliberately contradictory source metadata.
            JSONObject info=AudioQuality.info(new JSONObject().put("quality","lossless").put("type","aac").put("bitRate",96000).put("bitRateUnit","bps"));CountDownLatch stored=new CountDownLatch(1);boolean[] ok={false};cache.store(track,"AAC provenance","lossless",server.base()+"/quality-aac.m4a",new HashMap<>(),info,(success,message)->{ok[0]=success;stored.countDown();});check(stored.await(15,TimeUnit.SECONDS)&&ok[0],"AAC cache persistence failed");server.close();long old=service.snapshot().generation;JSONArray offline=new JSONArray().put(new JSONObject().put("uri",track).put("title","Offline source metadata").put("cacheOnly",true).put("cachedQuality","lossless"));ui(()->PlaybackService.startQueue(context,offline,0,0,80,false,false,"high"));tier(service,"lossless",old);clock(service);ui(()->{check(service.snapshot().offlineOnly&&service.snapshot().qualityInfo.contains("无损标注与编码不符"),"offline cached AAC became confirmed lossless");invoke(activity,"showPlaybackQuality");check(panel(activity).contains("无损标注与编码不符"),"actual quality panel hid cached source mismatch");((AlertDialog)FullPortChecks.field(activity,"qualityDialog")).dismiss();service.stopPlayback();check(!service.retryQuality(pendingFailure),"stopped session accepted a stale quality retry");});
            check(AudioQuality.describe(new JSONObject().put("quality","lossless").put("type","m4a")).contains("未核验"),"an ambiguous container was treated as a confirmed codec");
            System.out.println("MYGO_QUALITY_RETRY_OK: actual AAC native playback and paused-position retry; queue/modes/volume retained; same-song new session, delayed login, newer pending replacement and stopped-session stale callbacks rejected; open quality panel updates; contradictory lossless/AAC label stays explicit online and after stopped-server offline cache; unknown container remains unverified");
        }finally{
            ui(()->{service.clearQueue();manager.close();activity.finish();});for(String q:AudioQuality.VALUES)cache.remove(track,q);helper.cleanup(id);SharedPreferences.Editor edit=prefs.edit().clear();for(Map.Entry<String,?> entry:original.entrySet()){Object value=entry.getValue();String key=entry.getKey();if(value instanceof String)edit.putString(key,(String)value);else if(value instanceof Boolean)edit.putBoolean(key,(Boolean)value);else if(value instanceof Integer)edit.putInt(key,(Integer)value);else if(value instanceof Long)edit.putLong(key,(Long)value);else if(value instanceof Float)edit.putFloat(key,(Float)value);else if(value instanceof Set)edit.putStringSet(key,(Set<String>)value);}edit.commit();
        }
    }
}
